for p in pvals:
	pvals[p] = [np.exp(x) for x in pvals[p]]


th5 = int(5000*0.0242-1)
th1 = int(5000*0.01-1)

n = len(probas)

# choose grid size automatically
cols = math.ceil(np.sqrt(n))
rows = math.ceil(n / cols)
cols = 3
rows = 5

fig, axes = plt.subplots(rows, cols, figsize=(4*cols, 3*rows),sharex=True,sharey=True)
axes = np.array(axes).reshape(-1)

for i in range(n):
	axes[i].hist(probas[i], bins=100,color='thistle')
	
	popt = [0,0]
	popt[1] = 1/np.mean(probas[i])
	popt[0] = popt[1] * (max(probas[i]) - min(probas[i])) / 100 * len(probas[i])
	l = popt[1]
	pval1 = -(1/l) * math.log(1-0.01)
	pval5 = -(1/l) * math.log(1-0.05)
	pvalT = math.exp(-l * pvals[i][0]) - 1
	
	x = np.linspace(0, max(probas[i]), 500)
	axes[i].plot(x, exp_model(x, *popt), color='blue', lw=2)
	
	axes[i].scatter([pval1],[150],c='aquamarine')
	axes[i].scatter([pval5],[250],c='coral')
	
	if pvals[i][0] < pval5:
		axes[i].scatter([pvals[i][0]],[300],c='k')
	else:
		axes[i].scatter([pvals[i][0]],[300],c='k',marker='x')
	
	axes[i].set_title(f"T{i+1}")
	axes[i].annotate(str(round(pvalT,5)),(pvals[i][0],300))
		
	x1, x2 = -0.00025, 0.00075
	maxy = exp_model(0, *popt)
	y1, y2 = maxy+20-100, maxy+20
	
	axins = inset_axes(axes[i], width="35%", height="35%", loc="upper right")
	axins.hist(probas[i], bins=100, color='thistle')
	axins.plot(x, exp_model(x, *popt), color='blue', lw=2)
	axins.scatter([pval1], [maxy+20-20-30-30+10], c='aquamarine')
	axins.scatter([pval5], [maxy+20-20-30+10], c='coral')
	if pvals[i][0] < pval5:
		axins.scatter([pvals[i][0]], [maxy+20-20], c='k')
	else:
		axins.scatter([pvals[i][0]], [maxy+20-20], c='k', marker='x')
	
	axins.set_xlim(x1, x2)
	axins.set_ylim(y1, y2)
	axins.yaxis.set_visible(False)
	

for j in range(n, len(axes)):
	axes[j].axis("off")

plt.tight_layout()
plt.savefig('../figures_resultats/pvalues_sup_data.svg')
